1	export type Cell = [number, number];
2	
3	const MIN_NEIGHBORS_TO_SURVIVE = 2;
4	const MAX_NEIGHBORS_TO_SURVIVE = 3;
5	const NEIGHBORS_TO_BE_BORN = 3;
6	
7	const NEIGHBOR_OFFSETS = [-1, 0, 1];
8	
9	const key = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const neighborsOf = ([x, y]: Cell): Cell[] =>
12	  NEIGHBOR_OFFSETS.flatMap((dx) =>
13	    NEIGHBOR_OFFSETS.filter((dy) => dx !== 0 || dy !== 0).map(
14	      (dy): Cell => [x + dx, y + dy],
15	    ),
16	  );
17	
18	const countLiveNeighbors = (cell: Cell, aliveKeys: Set<string>): number =>
19	  neighborsOf(cell).filter((neighbor) => aliveKeys.has(key(neighbor))).length;
20	
21	const survives = (neighbors: number): boolean =>
22	  neighbors >= MIN_NEIGHBORS_TO_SURVIVE &&
23	  neighbors <= MAX_NEIGHBORS_TO_SURVIVE;
24	
25	const isBorn = (neighbors: number): boolean =>
26	  neighbors === NEIGHBORS_TO_BE_BORN;
27	
28	const dedupe = (cells: Cell[]): Cell[] => [
29	  ...new Map(cells.map((cell) => [key(cell), cell])).values(),
30	];
31	
32	const copyOf = ([x, y]: Cell): Cell => [x, y];
33	
34	// The live cell is copied so the returned generation never aliases the
35	// caller's input arrays; neighborsOf already produces fresh cells.
36	const candidateCells = (liveCells: Cell[]): Cell[] =>
37	  dedupe(liveCells.flatMap((cell) => [copyOf(cell), ...neighborsOf(cell)]));
38	
39	export function nextGeneration(liveCells: Cell[]): Cell[] {
40	  const aliveKeys = new Set(liveCells.map(key));
41	
42	  return candidateCells(liveCells).filter((cell) => {
43	    const neighbors = countLiveNeighbors(cell, aliveKeys);
44	
45	    return aliveKeys.has(key(cell)) ? survives(neighbors) : isBorn(neighbors);
46	  });
47	}
