1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	// The spec does not define an output ordering, so full-result comparisons sort
5	// both sides first. Sorting is value-based, so a missing or extra cell still fails.
6	const sorted = (cells: Cell[]): Cell[] =>
7	  [...cells].sort(([x, y], [otherX, otherY]) => y - otherY || x - otherX);
8	
9	// The 2x2 block: every live cell has exactly 3 live neighbours, so the whole
10	// shape is a still life. Used by both the survival and the still-life tests.
11	const BLOCK: Cell[] = [
12	  [0, 0],
13	  [1, 0],
14	  [0, 1],
15	  [1, 1],
16	];
17	
18	// The blinker's two phases. Each is the other's next generation, so both appear
19	// once as an input and once as an expectation. Safe to share: nextGeneration
20	// never aliases or mutates its argument.
21	const VERTICAL_BLINKER: Cell[] = [
22	  [0, 0],
23	  [0, 1],
24	  [0, 2],
25	];
26	
27	const HORIZONTAL_BLINKER: Cell[] = [
28	  [-1, 1],
29	  [0, 1],
30	  [1, 1],
31	];
32	
33	describe("Game of Life - Next Generation", () => {
34	  it("should return an empty grid for an empty grid — [] -> []", () => {
35	    expect(nextGeneration([])).toEqual([]);
36	  });
37	
38	  it("should kill a single live cell with 0 neighbors (underpopulation) — [(0,0)] -> []", () => {
39	    expect(nextGeneration([[0, 0]])).toEqual([]);
40	  });
41	
42	  it("should kill both live cells when each has only 1 neighbor (underpopulation) — [(0,1), (1,1)] -> []", () => {
43	    expect(
44	      nextGeneration([
45	        [0, 1],
46	        [1, 1],
47	      ]),
48	    ).toEqual([]);
49	  });
50	
51	  // NOTE: the spec's Rule 2 illustration (`###`/`...`/`.#.` -> `.#.`/`.#.`/`...`)
52	  // is not reproducible under Conway's rules: its centre (1,1) is dead with 4
53	  // live neighbours, and the true next generation is [(1,-1),(0,1),(1,0),(2,1)].
54	  // The spec's *statement* of Rule 2 is sound, so we test that statement using
55	  // the block, where every live cell has exactly 3 neighbours and survives.
56	  it("should keep a live cell with 3 live neighbors alive (survival) — (0,0) of the block has 3 neighbors and survives", () => {
57	    expect(nextGeneration(BLOCK)).toContainEqual([0, 0]);
58	  });
59	
60	  // NOTE: as with Rule 2, the spec's Rule 3 illustration is inaccurate. In
61	  // `###`/`.#.`/`###` the centre (1,1) has 6 live neighbours, not the 4 the
62	  // prose claims, and the drawn Gen 1 (`#.#`/`#.#`/`#.#`) is not the true next
63	  // generation. The asserted *behaviour* is nonetheless correct: the centre is
64	  // overpopulated and dies, so we assert its absence rather than the drawing.
65	  it("should kill a live cell with 4 live neighbors (overpopulation) — center (1,1) of `###`/`.#.`/`###` dies", () => {
66	    const grid: Cell[] = [
67	      [0, 0],
68	      [1, 0],
69	      [2, 0],
70	      [1, 1],
71	      [0, 2],
72	      [1, 2],
73	      [2, 2],
74	    ];
75	
76	    expect(nextGeneration(grid)).not.toContainEqual([1, 1]);
77	  });
78	
79	  it("should bring a dead cell with exactly 3 live neighbors to life (reproduction) — (1,1) of `##.`/`#..`/`...` becomes alive", () => {
80	    const grid: Cell[] = [
81	      [0, 0],
82	      [1, 0],
83	      [0, 1],
84	    ];
85	
86	    expect(nextGeneration(grid)).toContainEqual([1, 1]);
87	  });
88	
89	  it("should keep a block unchanged (still life) — [(0,0), (1,0), (0,1), (1,1)] -> unchanged", () => {
90	    expect(sorted(nextGeneration(BLOCK))).toEqual(sorted(BLOCK));
91	  });
92	
93	  it("should turn a vertical blinker horizontal — [(0,0), (0,1), (0,2)] -> [(-1,1), (0,1), (1,1)]", () => {
94	    expect(sorted(nextGeneration(VERTICAL_BLINKER))).toEqual(
95	      sorted(HORIZONTAL_BLINKER),
96	    );
97	  });
98	
99	  // Asserted as a transition in its own right rather than as
100	  // nextGeneration(nextGeneration(vertical)): chaining would make a regression in
101	  // generation 1 fail this test too, hiding which transition actually broke.
102	  it("should turn the horizontal blinker back to vertical — [(-1,1), (0,1), (1,1)] -> [(0,0), (0,1), (0,2)]", () => {
103	    expect(sorted(nextGeneration(HORIZONTAL_BLINKER))).toEqual(
104	      sorted(VERTICAL_BLINKER),
105	    );
106	  });
107	
108	  // Offset entirely into negative space (both axes) rather than reusing
109	  // HORIZONTAL_BLINKER, which already contains a single negative x — this covers
110	  // the spec's "infinite in all directions" constraint with coordinates the other
111	  // tests never reach.
112	  it("should handle negative coordinates — a blinker at negative coordinates oscillates", () => {
113	    const vertical: Cell[] = [
114	      [-5, -5],
115	      [-5, -4],
116	      [-5, -3],
117	    ];
118	    const horizontal: Cell[] = [
119	      [-6, -4],
120	      [-5, -4],
121	      [-4, -4],
122	    ];
123	
124	    expect(sorted(nextGeneration(vertical))).toEqual(sorted(horizontal));
125	    expect(sorted(nextGeneration(horizontal))).toEqual(sorted(vertical));
126	  });
127	});
